import { html, nothing } from 'lit';
import { classMap } from 'lit/directives/class-map.js';
import { OtcMenuItemBase } from './otcMenuItemBase.js';
import { ThemeController } from '../../controllers/themeController.js';
import buttonStyleSheet from '../button/otcButton.scss';
import buttonJatoStyleSheet from '../button/otcButtonJato.scss';
import menuActionItemStyleSheet from './otcMenuActionItem.scss';

export class OtcMenuActionItem extends OtcMenuItemBase {
  #themeController = new ThemeController(this);

  static get styles() {
    return [
      ...OtcMenuItemBase.styles,
      buttonStyleSheet,
      buttonJatoStyleSheet,
      menuActionItemStyleSheet,
    ];
  }

  static get properties() {
    const props = { };

    return { ...ThemeController.properties, ...props };
  }

  render() {
    const dropdownItemClasses = {
      'ot-btn': this._themeIsCarbonFiber,
      'ot-btn--is-mini': this._themeIsCarbonFiber,
      'ot-btn--is-secondary': this._themeIsCarbonFiber,
      'ot-btn-jato': !this._themeIsCarbonFiber,
      'ot-btn-jato--is-more': !this._themeIsCarbonFiber,
      ...this.baseClasses,
    };

    return html`
      <div class="ot-dropdown__action-item" role="none">
        <li
          id="menuactionitem-dropdownitem"
          class=${classMap(dropdownItemClasses)}
          role="menuitem"
          tabindex="-1"
          aria-label=${this.ariaLabel.length > 0 ? this.ariaLabel : nothing}
        >
          <slot></slot>
        </li>
      </div>
    `;
  }
}

customElements.define('otc-menuactionitem', OtcMenuActionItem);
